struct Chat
{
    string nom;
    int age;
};

int main()
{
    vector<Chat> refuge = { { "Mimi", 3 }, { "Tigrou", 10 } };
    ofstream fichier("refuge.txt");
    for (const Chat& chat : refuge)
    {
        fichier << chat.nom << ';' << chat.age << '\n';
    }
    fichier.close();
    return 0;
}

