struct Chat
{
    string nom;
    int age;
};

int main()
{
    vector<Chat> refuge;
    ifstream fichier("refuge.txt");
    string ligne;
    while (getline(fichier, ligne))
    {
        size_t pos = ligne.find(';');
        Chat chat;
        chat.nom = ligne.substr(0, pos);
        chat.age = stoi(ligne.substr(pos + 1));
        refuge.push_back(chat);
    }
    fichier.close();
    cout << refuge.size() << " chats, le 2e : " << refuge[1].nom << '\n';
    return 0;
}

